namespace TransactionImport.Application.Abstractions;

public sealed record StoredObject(string Key, long SizeBytes, DateTimeOffset LastModified);

/// <summary>
/// Object storage for uploaded files. Keys are always generated by the service (never derived from client
/// file names). Implementations must stream: neither writes nor reads may buffer whole objects in memory.
/// </summary>
public interface IFileStorage
{
    /// <summary>Writes the stream to <paramref name="key"/>. The object becomes visible only once fully written.</summary>
    Task WriteAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Opens the object for sequential reading starting at <paramref name="offset"/>.</summary>
    /// <exception cref="StorageObjectNotFoundException">The object does not exist.</exception>
    Task<Stream> OpenReadAsync(string key, long offset, CancellationToken cancellationToken);

    Task DeleteAsync(string key, CancellationToken cancellationToken);

    /// <summary>Lists objects under <paramref name="prefix"/>, ordered by key.</summary>
    Task<IReadOnlyList<StoredObject>> ListAsync(string prefix, CancellationToken cancellationToken);
}

public sealed class StorageObjectNotFoundException : Exception
{
    public StorageObjectNotFoundException(string key)
        : base($"Storage object '{key}' was not found.")
    {
        Key = key;
    }

    public string Key { get; }
}
